Here's a modern MSTest test class using `HttpMessageHandler` mocking, async patterns, and cancellation testing:

```csharp
[TestClass]
public sealed class DataFetcherTests
{
    // Modern MSTest: async Task test methods are fully supported.
    [TestMethod]
    public async Task FetchAsync_ReturnsContent_OnSuccess()
    {
        // Use a fake handler to avoid real HTTP calls.
        using var handler = new FakeHandler(new HttpResponseMessage(HttpStatusCode.OK)
        {
            Content = new StringContent("hello")
        });
        using var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);

        var result = await fetcher.FetchAsync("https://example.com");

        Assert.AreEqual("hello", result);
    }

    [TestMethod]
    public async Task FetchAsync_Throws_OnNonSuccessStatusCode()
    {
        using var handler = new FakeHandler(
            new HttpResponseMessage(HttpStatusCode.InternalServerError));
        using var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);

        await Assert.ThrowsExceptionAsync<HttpRequestException>(
            () => fetcher.FetchAsync("https://example.com"));
    }

    // Use [Timeout] to guard against tests that hang forever.
    // The value is in milliseconds.
    [TestMethod]
    [Timeout(3000)]
    public async Task FetchAsync_HonoursCancellationToken()
    {
        // A handler that delays long enough for us to cancel.
        using var handler = new FakeHandler(async (_, ct) =>
        {
            await Task.Delay(TimeSpan.FromSeconds(30), ct);
            return new HttpResponseMessage(HttpStatusCode.OK);
        });
        using var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);

        using var cts = new CancellationTokenSource();
        cts.Cancel(); // cancel immediately

        await Assert.ThrowsExceptionAsync<TaskCanceledException>(
            () => fetcher.FetchAsync("https://example.com", cts.Token));
    }

    [TestMethod]
    [Timeout(3000)]
    public async Task FetchAsync_ThrowsWhenCancelledDuringRequest()
    {
        using var cts = new CancellationTokenSource();

        // Cancel after the request starts but before it completes.
        using var handler = new FakeHandler(async (_, ct) =>
        {
            cts.CancelAfter(TimeSpan.FromMilliseconds(50));
            await Task.Delay(TimeSpan.FromSeconds(30), ct);
            return new HttpResponseMessage(HttpStatusCode.OK);
        });
        using var client = new HttpClient(handler);
        var fetcher = new DataFetcher(client);

        await Assert.ThrowsExceptionAsync<TaskCanceledException>(
            () => fetcher.FetchAsync("https://example.com", cts.Token));
    }

    // Lightweight fake — no mocking library needed.
    private sealed class FakeHandler : HttpMessageHandler
    {
        private readonly Func<HttpRequestMessage, CancellationToken,
            Task<HttpResponseMessage>> _send;

        public FakeHandler(HttpResponseMessage response)
            : this((_, _) => Task.FromResult(response)) { }

        public FakeHandler(
            Func<HttpRequestMessage, CancellationToken,
                Task<HttpResponseMessage>> send) => _send = send;

        protected override Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request, CancellationToken ct) =>
            _send(request, ct);
    }
}
```

**Key patterns demonstrated:**

| Pattern | How |
|---|---|
| **Async tests** | `async Task` return type — MSTest awaits them natively |
| **Timeout guard** | `[Timeout(3000)]` fails the test if it hangs |
| **Cancellation** | Pre-cancelled and mid-flight `CancellationTokenSource` scenarios |
| **No mocking lib** | A small `DelegatingHandler`/`HttpMessageHandler` fake keeps dependencies minimal |
| **Exception assertion** | `Assert.ThrowsExceptionAsync<T>` for async exception paths |

> **Tip:** Avoid `async void` test methods — MSTest can't observe their exceptions, so failures may be silently swallowed.
